=Here are the analysis results from HopZero. Please summarize them.

Investigation ID: {{ $('Set Input ID').item.json.investigation_id }}

Analysis Run Status: {{ $('Get Analysis Run').item.json.status }}

Findings:
{{ JSON.stringify($('Get Findings').item.json, null, 2) }}

Evidence:
{{ JSON.stringify($json, null, 2) }}

Score Information:
{{ JSON.stringify($('Get Score').item.json, null, 2) }}

=The analysis did not complete successfully.

Investigation ID: {{ $('Set Input ID').item.json.investigation_id }}
Analysis Run Status: {{ $('Get Analysis Run').item.json.status }}

Please report this failure state.

parameters.jsCode:
const expectedRunId = $('Store Run ID').item.json.analysis_run_id;
const scoreRunId = $('Get Score').item.json.analysis_run_id;

if (scoreRunId !== expectedRunId) {
    throw new Error('Data Consistency Error: Score run ID ' + scoreRunId + ' does not match polled run ID ' + expectedRunId);
}

const findings = $('Get Findings').item.json || [];
const findingsArr = Array.isArray(findings) ? findings : [findings];

for (const f of findingsArr) {
    if (f.analysis_run_id && f.analysis_run_id !== expectedRunId) {
        throw new Error('Data Consistency Error: Finding ' + f.id + ' belongs to run ' + f.analysis_run_id + ', not ' + expectedRunId);
    }
}

return [{ json: { consistency: 'VERIFIED', run_id: expectedRunId } }];

